"""Completed single-round and two-round evidence; old traces remain separate."""
import json
from pathlib import Path
from html import escape
from build_site import e,link,p,small,table
from prethinking_trace_content import verbatim

ROOT=Path(__file__).resolve().parents[1]

def load_completion():
    path=ROOT/'research/prethinking-pilot/completion.json'
    return json.loads(path.read_text()) if path.exists() else None

def eq(tex):return '<div class="equation" tabindex="0" role="region" aria-label="Equation; scroll horizontally if needed">\\['+escape(tex)+'\\]</div>'

def completion_results(bundle,data):
    if not bundle:return ''
    s=bundle['summary'];r=bundle['review'];cs=bundle['calls'];a=bundle['accounting'];first=cs[0];job_set=a['jobs']
    body=p('The completion follow-up separates a single-round example from two-round teacher tests. A round is one delivered input update, which may bundle several speaker-attributed transcript segments. The single-round example receives the transcript available through 640 s and no earlier pre-thinking. Its six new segments are numbered in Figure 2. The archived call-54 prompt is replayed separately with its four original private-history entries; it is not presented as a history-free example.')
    body+=p('The single-round response now ends naturally: '+str(first['private_token_count'])+' private-thinking tokens and '+str(first['output_tokens'])+' total generated tokens, including the thinking closing marker, final notes and the terminal EOS token, over '+f"{first['wall_seconds']:.3f}"+' s. Private-thinking completion means the model emitted its closing thinking marker; response completion also requires a normal stop. Neither condition establishes grounding or usefulness. The full-completion option in Figure 2 holds the same transcript fixed; the short window still truncates at the next delivered update.')
    body+='<div class="callout"><h3>Completion is separate from evidence quality</h3>'+p(r.get('content_conclusion','Read the content review below before considering these outputs as supervision.'))+'</div>'
    body+=p(str(r['completion_passes'])+' of ten calls have a closed thinking block and a natural response stop; all ten reach normal EOS. The remaining continuation is a recorded format failure, not a completed CoT. All source IDs in parsed notes refer to already observed input, but content review shows that a real ID can still cite the wrong text.')
    body+=p(r.get('structured_note_failure',''))
    body+='<h3>Measured generation speed and inference setup</h3>'
    body+=p('All measured calls use one A100-SXM4 80 GB on GPU 0, solely for the pinned Qwen3-30B-A3B-Thinking-2507 teacher. There is no S1, speech, ASR, diarization or competing request in this job. BF16 weights, tensor parallelism 1, one sequence, eager execution, 49,152-token maximum context, a fixed 6 GiB KV cache and 2,048-token prefill batches are used. Prefix caching is disabled; CUDA graphs and Inductor compilation are disabled. The log selects FlashAttention and the default unquantized Triton MoE configuration; this is a measured local setup, not the model’s fastest possible serving configuration.')
    body+=p('Software: vLLM '+s['software']['vllm']+', PyTorch '+s['software']['torch']+', Transformers '+s['software']['transformers']+'. Sampling is temperature 0.6, top-p 0.95, top-k 20 and seed 17. Each call permits up to 32,768 new tokens, reduced only if the remaining context is smaller; EOS is respected. The official model card recommends these sampling values and a substantially larger output allowance than the old 570-token capture.')+link('Qwen model card and generation guidance','https://huggingface.co/Qwen/Qwen3-30B-A3B-Thinking-2507')
    body+=p('Three sequential allocations were used, preserving earlier generated calls after two pipeline stops. Engine startup per job took '+', '.join(job['job_id']+': '+f"{job['startup_seconds']:.3f} s" for job in job_set)+' including loading and built-in model warm-up. Each job used two further explicit generation warm-ups: a short arithmetic prompt and the original 6,814-token call-54 prompt, each capped at 64 output tokens. Their durations are '+', '.join(job['job_id']+': '+('/'.join(f"{w['wall_seconds']:.3f} s" for w in job['warmups'])) for job in job_set)+'. Warm-ups and startup are excluded from the study rates. Every measured prompt is tokenized on CPU before submitting its token IDs; that preparation time is recorded separately. All calls then run sequentially in the same warmed engine.')
    body+=p('“Output/wall” divides all generated tokens by request duration, including prefill and engine/driver overhead. “Decode” counts tokens received after the first receipt divided by the interval from first to last receipt. Receipt times are observed on the host after each vLLM engine step; several tokens can arrive together. These are approximate delivered-token speeds, not isolated GPU kernel timings. Copied history and prefilled thinking are input tokens and are excluded from generation counts. Across the ten calls, the weighted rates are '+f"{r['weighted_output_tokens_per_wall_second']:.2f}"+' tokens/s for output/wall and '+f"{r['weighted_decode_tokens_per_second']:.2f}"+' tokens/s for decode. The timeline’s 0.5 s setup and 10/30/60/100 rates remain separate illustrative assumptions.')
    body+=table('completion-speed-table',0,'Measured teacher requests after two explicit warm-ups. Token counts include generated private reasoning and final notes; copied history is excluded.', ['Call / condition','Input / generated tokens','Private tokens / completion','First token / request wall','Output/wall / decode'],[
        [link('New call '+str(c['index']),'#completion-call-'+str(c['index']),'completion-link')+small(c['sample']+' · round '+str(c['round']+1)+' · '+c['mode']),str(c['input_tokens'])+' / '+str(c['output_tokens']),(str(c['private_token_count']) if c['thinking_closed'] else 'Undelimited')+small('CoT closed; natural stop' if c['natural_response_complete'] else 'EOS without closing CoT marker'),f"{c['first_token_seconds']:.3f} s / {c['wall_seconds']:.3f} s",f"{c['output_tokens_per_wall_second']:.2f} / {c['decode_tokens_per_second']:.2f} tokens/s"] for c in cs
    ],searchable=False)
    body+=p('Allocations: '+', '.join(j['job_id']+' on '+j['node']+' ('+str(j['elapsed_seconds'])+' s)' for j in job_set)+', each one A100-SXM4 80 GB. Total '+str(a['elapsed_seconds'])+' allocated seconds / '+f"{a['gpu_hours']:.5f}"+' GPU-hours. Sampled peak '+f"{r['sampled_peak_mib']/1024:.2f}"+' GiB. Dependencies are the existing pinned model and CPU preflight. Maximum one experiment GPU active; cases are sequential with no automatic fallback. Audits, exports and browser checks use 0 GPUs.')
    body+=p('Job 1074045 saved calls 0–2 before a multiline JSON/verbatim assertion stopped the pipeline. The history representation was corrected to a verbatim labeled block, with a real multiline preflight. Job 1074192 saved calls 3–4, then stopped because the runner treated the observed literal-continuation format failure as fatal to the entire pilot. The final job preserved all five calls and ran only calls 5–9; candidate format failures are now recorded while remaining controls execute. Both stopped allocations were cancelled during lingering worker cleanup. No completed call was regenerated, no GPU OOM occurred and no multi-GPU fallback was used. Source job is recorded per call; model, sampling and hardware type are otherwise unchanged.')
    body+='<details><summary>Frozen executed recipes and source</summary><p>'+ ' · '.join(link('Launch '+str(n)+' driver','../research/prethinking-pilot/completion-source/launch-0'+str(n)+'/run_prethinking_completion.py')+' / '+link('config','../research/prethinking-pilot/completion-source/launch-0'+str(n)+'/config.json')+' / '+link('job template','../research/prethinking-pilot/completion-source/launch-0'+str(n)+'/prethinking_completion_a100.sbatch') for n in [1,2,3])+' · '+link('Case cutoffs and review questions','../research/prethinking-pilot/completion-source/cases.json')+'</p>'+p('The job template requests 45 minutes; the two resume submissions override it to 35 minutes and add afterany dependencies. Calls 0–2 use launch 01, calls 3–4 launch 02, and calls 5–9 launch 03. The frozen configs preserve the checkpoint revision and input paths; prepared manifests retain hashes. Reproduction assumes the existing pinned local checkpoint and uv environment described above.')+'</details>'
    body+='<h3>Does the grouped teacher / interleaved student proposal make sense?</h3>'
    body+=p(r'Yes, as a causal distillation proposal. Let \(T_t\) be the newly available attributed transcript at round \(t\), \(x_t\) its audio counterpart, \(z_t\) the new private-thinking text, and \(c\) the instructions and participant perspective. Write \(R_t\) for the retained pre-thinking record. In this pilot \(R_t\) includes private thinking and its final notes; the student must receive those same notes if the teacher conditions on them. A private-only variant should remove notes from both sides. The teacher groups all observed transcript and earlier records; the student interleaves audio and those same earlier records:')
    body+=eq(r'\begin{aligned}z_t&\sim q_T\!\left(z\mid T_0,\ldots,T_t,R_0,\ldots,R_{t-1},c\right),\\p_\theta&\!\left(z_t\mid x_0,R_0,\ldots,x_{t-1},R_{t-1},x_t,c\right).\end{aligned}')
    body+=p('Only earlier pre-thinking enters the teacher input: “all pre-thinks” must exclude the current target and any later reasoning. The different serialization order can help a teacher inspect the evidence, but it is not guaranteed to improve quality. It adds no future evidence. Ground-truth text is privileged modality supervision for the audio student; its cutoff still needs to match the actual available audio/text. The student training loss should supervise only the newly generated target, not copied historical text or the teacher’s authored continuation separator:')
    body+=eq(r'\mathcal{L}_{\mathrm{distill}}=-\sum_t\sum_{k=1}^{|z_t|}\log p_\theta\!\left(z_{t,k}\mid x_0,R_0,\ldots,x_t,z_{t,<k},c\right).')
    body+=p('Retaining every previous full thought will quickly consume context: the single-round private trace alone has 4,660 tokens, while this runtime allows 49,152 total input-plus-output tokens. Long conversations need an explicit retention or compression policy. Any summary must use only then-available evidence; the teacher and student must receive compatible retained state. The two-round pilot does not establish that an unbounded list of prior thoughts is practical.')
    body+=p('A completed thinking block can be used as context for a later update, or its private text can be copied into an open thinking prefix and extended. Those are distinct experiments. Continuing analysis should preserve facts while revising assumptions; it should not commit to the old direction or present earlier guesses as participant statements. If the prior block was interrupted mid-sentence, simple string continuation may be especially brittle.')
    body+=p('The pinned native Qwen chat template removes earlier assistant reasoning before a later user turn; the CPU preflight demonstrates this with a unique test string. The old raw-history pipeline avoided that by serializing earlier reasoning explicitly, and its original call 54 really contains four entries. The new conditions below likewise preserve it explicitly. No model KV cache is resumed after changing the input.')+link('Hugging Face chat-template continuation semantics','https://huggingface.co/docs/transformers/main/en/chat_templating')
    body+=table('completion-conditions-table',0,'Two-round teacher conditions share the same first-round output within each sample. Round-two reset is a control, not a two-round history condition.', ['Condition','Teacher input / new generation','What this tests'],[
        [e('Conditioned new reasoning'),e('All observed transcript, the exact previous private thinking and final notes; then a fresh native thinking prefix.'),e('Whether earlier work is used and revised without copying it into the output target.')],
        [e('Prefilled continuation'),e('All observed transcript and previous notes; the prior private thinking is copied into an open native thinking prefix, followed by a labeled current-update separator. Only the generated suffix is the target.'),e('Literal continuation of prior thinking versus a new analysis conditioned on it.')],
        [e('Reset control'),e('The same observed transcript/current IDs, with no earlier private thinking or notes.'),e('Whether retaining generated history improves content relative to transcript alone.')]
    ],searchable=False)
    body+=p('The commitment sample moves from A volunteering at 100.69 s to A’s end-of-week deadline at 115.67 s. The deadline sample moves from setting up the deadline discussion at 1795.87 s to the whole-month rejection, proposed mid-March date, and title/abstract sequence by 1829.92 s. Every round-two history is exactly that sample’s actual round-one output. The two samples and one seed are diagnostic examples, not an estimate of average quality.')
    body+=p('The samples do not establish that grouped teacher input is better than the student-style interleaving: that requires a separate same-model, same-evidence serialization control. The concrete next prompt changes are to require proposition text in each note, define whether the output is an incremental update or full state, and verify quoted text against its cited chunk before accepting supervision. Full private CoT must retain uncertainty and let current evidence override earlier analysis.')
    body+=p('This two-round pilot generates complete previous teacher reasoning offline, without requiring it to fit the real interval between inputs. It is causal with respect to transcript content but does not demonstrate real-time feasibility. A timed multi-round replay must instead retain only emitted prefixes. During student training, teacher-generated history also differs from the student’s eventual generated history; training/evaluation with student-generated records and imperfect speaker recognition will be needed. No audio student is trained here.')
    findings=r.get('qualitative_findings',[])
    if findings:
        body+='<h3>Actual transcript and new thinking examples</h3>'
        by_chunk={c['id']:c for c in data['chunks']};rows=[]
        for f in findings:
            c=cs[f['call_index']];assert c['private_reasoning'][f['cot_start']:f['cot_end']]==f['cot_excerpt']
            source=''.join('<div class="trace-example-source">'+small(i+' · '+by_chunk[i]['speaker'])+'<blockquote>'+e(by_chunk[i]['text'])+'</blockquote></div>' for i in f['transcript_chunk_ids'])
            rows.append([e(f['category'])+small(f['status']),source,'<pre class="trace-excerpt">'+verbatim(f['cot_excerpt'])+'</pre>'+link('Full new thinking and prompt','#completion-call-'+str(c['index']),'completion-link'),e(f['assessment'])])
        body+=table('completion-example-table',0,'Verbatim completed-run thinking versus real source chunks. Quality labels apply to these selected passages; completion alone is not a pass.', ['Condition / finding','Actual transcript','Actual generated private thinking','Assessment'],rows)
    return body

def completion_appendix(bundle,data):
    if not bundle:return ''
    chunks={c['id']:c for c in data['chunks']}
    body=p('These ten calls come from three sequential completion allocations, consolidated after job '+bundle['job_id']+'. They preserve each exact executed prompt and generated private-thinking suffix. Prefilled/copied old thinking is visible in the prompt and is not counted as newly generated reasoning. The original 64 capped traces are preserved in the following historical appendix.')
    body+='<p>'+link('Download original new calls as byte-exact JSONL','../research/prethinking-pilot/completion_calls.jsonl')+' · '+link('Completed-run prompts, tokens, receipt times and review','../research/prethinking-pilot/completion.json')+'</p>'
    for c in bundle['calls']:
        index=c['index'];body+='<details class="completion-record trace-record-style" id="completion-call-'+str(index)+'" data-call="'+str(c['plot_index'])+'"><summary>'+e('New call '+str(index)+' · '+c['sample']+' · round '+str(c['round']+1)+' · '+c['mode']+' · '+f"{c['at']:.2f} s")+'</summary>'
        body+=p('Input '+str(c['input_tokens'])+' tokens; '+('new private thinking '+str(c['private_token_count'])+' tokens' if c['thinking_closed'] else 'generated continuation has no private/final phase boundary')+'; total output '+str(c['output_tokens'])+' tokens; '+str(c['retained_history_entries'])+' prior entries. '+('Private thinking closes and response stops naturally.' if c['natural_response_complete'] else 'The response reaches EOS without a closing thinking marker; the continuation is not a valid completed native CoT trace.')+' Source job '+c['call_source_job']+'. Prompt preparation '+f"{c['prompt_prepare_seconds']:.4f}"+' s; request '+f"{c['wall_seconds']:.3f}"+' s; approximate decode '+f"{c['decode_tokens_per_second']:.2f}"+' tokens/s.')
        body+='<h3>Current transcript update</h3>'
        for ident in c['new_ids']:
            chunk=chunks[ident];body+='<div class="trace-input">'+small(ident+' · speaker '+chunk['speaker']+' · speech '+f"{chunk['start']:.2f}–{chunk['end']:.2f} s"+' · available '+f"{chunk['available']:.2f} s")+'<blockquote>'+e(chunk['text'])+'</blockquote></div>'
        body+='<p>'+link('Inspect this captured output on the timeline','#thinking-timeline','completion-focus-link')+'</p>'
        body+='<details class="trace-prompt-details"><summary>Exact executed prompt, including every retained/pre-filled entry</summary><pre class="trace-prompt" id="completion-prompt-'+str(index)+'">'+verbatim(c['prompt'])+'</pre></details>'
        body+=('<h3>Newly generated private-thinking continuation</h3>' if c['thinking_closed'] else '<h3>Undelimited generated continuation: no closing thinking marker</h3>')+'<pre class="trace-thinking" id="completion-thinking-'+str(index)+'">'+verbatim(c['private_reasoning'])+'</pre>'
        if c['thinking_closed']:body+='<h3>Final notes</h3><pre class="trace-final">'+verbatim(c['final_text'])+'</pre>'
        else:body+=p('No separately delimited final notes were produced. All captured continuation text is shown above.')
        body+='<details><summary>Exactness checks</summary>'+p('Prompt SHA-256: '+c['prompt_sha256'])+p('Thinking SHA-256: '+c['thinking_sha256'])+p('Generated output SHA-256: '+c['generated_sha256'])+'</details></details>'
    return body

def completion_timeline(bundle):
    if not bundle:return []
    fields=['stage','sample','round','variant','at','new_ids','seed','history_mode','budget','output_tokens','next_arrival','generated_text','generated_token_ids','token_byte_ends','private_token_count','thinking_closed','natural_response_complete','finish_reason','wall_seconds','first_token_seconds','decode_tokens_per_second','appendix_id','previous_call']
    result=[]
    for c in bundle['calls']:
        row={k:c[k] for k in fields if k in c};row.update(index=c['plot_index'],source_index=c['index'],source_job=c['call_source_job'])
        if c['stage']=='two_round' and c['round']==0:
            row['next_arrival']=115.67 if c['sample']=='commitment' else 1829.92
        if 'previous_call' in c:row['previous_plot_index']=100+c['previous_call']
        result.append(row)
    return result
